)

func main() {
	if err := run(); err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
}

func run() error {
	if dir := tmuxRepositoryDir(); dir != "" {
		if err := os.Chdir(dir); err != nil {
			return fmt.Errorf("change to tmux repository directory: %w", err)
		}
	}

	remotes, err := gitRemotes()
	if err != nil {
		return err
	}
	if len(remotes) == 0 {
